// Inicializa os dados do gráfico
let pieChartData = [];

// Define cores específicas para IPv4 e IPv6
const colorPalette = {
  "TOTAL ROTAS IPV4": ['#00E96A', '#006c4c'], // Verde para IPv4
  "TOTAL ROTAS IPV6": ['#2196F3', '#0031ff']  // Azul para IPv6
};

// Processa os dados do Grafana para obter os valores
context.panel.data.series.forEach((series) => {
  const fieldNameField = series.fields.find((f) => f.name.toLowerCase() === 'field');
  const routeCountField = series.fields.find((f) => f.name.toLowerCase() === 'last *');

  if (fieldNameField && routeCountField) {
    for (let i = 0; i < fieldNameField.values.length; i++) {

      // ===== NOVA LÓGICA PARA LER O ALIAS E FILTRAR =====

      // 1. Pega o alias completo (ex: "TOTAL ROTAS IPV4;VERSAO=ipv4")
      const rawAlias = fieldNameField.values.get(i);

      // 2. Separa o nome da rota e o valor da variável
      const parts = rawAlias.split(';VERSAO=');
      const routeType = parts[0]; // "TOTAL ROTAS IPV4"
      const selectedVersion = parts[1] || 'all'; // "ipv4", "ipv6" ou o valor de 'All'

      // 3. Verifica se a opção 'All' está selecionada
      const showAll = selectedVersion.toLowerCase().includes('all') || selectedVersion.includes(',');

      // 4. Lógica de exibição: continua apenas se 'All' estiver selecionado OU se o nome da rota corresponder à seleção
      let formattedName = routeType.replace("TOTAL ROTAS", "").trim();
      const shouldDisplay = showAll || formattedName.toLowerCase().includes(selectedVersion.toLowerCase());

      if (shouldDisplay) {
        // Pega o valor numérico
        const routeCount = routeCountField.values.get(i);

        // Define a cor usando o nome original da rota
        const color = colorPalette[routeType] || ['#9E9E9E', '#616161'];

        // Adiciona os dados ao gráfico
        pieChartData.push({
          name: formattedName,
          value: routeCount,
          itemStyle: {
            color: new context.echarts.graphic.LinearGradient(0, 0, 0, 1, [
              { offset: 0, color: color[0] },
              { offset: 1, color: color[1] }
            ]),
            borderColor: 'rgba(0,0,0,1)',
            borderWidth: 1.5,
          }
        });
      }
      // ======================================================
    }
  }
});

// O resto do seu código original permanece igual
return {
  backgroundColor: 'transparent',
  title: {
    text: '',
    left: 'center',
    textStyle: {
      color: '#FFFFFF',
      fontSize: 24,
      fontWeight: 'bold'
    }
  },
  tooltip: {
    trigger: 'item',
    formatter: '{b}: {c} ({d}%)'
  },
  legend: {
    orient: 'horizontal',
    bottom: '5%',
    data: pieChartData.map((item) => item.name),
    textStyle: {
      color: '#FFFFFF',
      fontSize: 12
    }
  },
  series: [
    {
      name: 'Rotas',
      type: 'pie',
      radius: ['30%', '60%'],
      center: ['50%', '50%'],
      data: pieChartData,
      label: {
        formatter: '{c}',
        color: '#FFFFFF',
        fontSize: 14,
        fontWeight: 'bold'
      },
      labelLine: {
        length: 16,
        length2: 16,
        lineStyle: {
          color: '#FFFFFF',
          width: 3,
        }
      },
      itemStyle: {
        borderRadius: 10,
        shadowBlur: 10,
        shadowColor: 'rgba(0, 0, 0, 0.5)'
      }
    }
  ]
};
